"js/utils.js": function(module, exports, __require) {
function normalizeAnswer(value = '') {
  return String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function answerMatches(value, accepted = []) {
  const normalized = normalizeAnswer(value);
  return accepted.some((candidate) => normalizeAnswer(candidate) === normalized);
}

function escapeHtml(value = '') {
  return String(value).replace(/[&<>'"]/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;'
  })[character]);
}

function formatDuration(milliseconds) {
  const total = Math.max(0, Math.floor(milliseconds / 1000));
  const hours = String(Math.floor(total / 3600)).padStart(2, '0');
  const minutes = String(Math.floor((total % 3600) / 60)).padStart(2, '0');
  const seconds = String(total % 60).padStart(2, '0');
  return `${hours}:${minutes}:${seconds}`;
}

function unique(items) {
  return [...new Set(items)];
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function daysSince(dateString) {
  const start = new Date(dateString);
  const now = new Date();
  const delta = Math.max(0, now - start);
  return {
    days: Math.floor(delta / 86400000),
    hours: Math.floor((delta % 86400000) / 3600000),
    minutes: Math.floor((delta % 3600000) / 60000),
    seconds: Math.floor((delta % 60000) / 1000)
  };
}

function shuffledStable(items, seed = 17) {
  return [...items].sort((a, b) => {
    const left = String(a).split('').reduce((sum, char) => sum + char.charCodeAt(0) * seed, 0);
    const right = String(b).split('').reduce((sum, char) => sum + char.charCodeAt(0) * seed, 0);
    return (left % 97) - (right % 97);
  });
}

exports.normalizeAnswer = normalizeAnswer;
exports.answerMatches = answerMatches;
exports.escapeHtml = escapeHtml;
exports.formatDuration = formatDuration;
exports.unique = unique;
exports.clamp = clamp;
exports.daysSince = daysSince;
exports.shuffledStable = shuffledStable;
},
"js/room-model.js": function(module, exports, __require) {
const REQUIRED_OBJECTS = ['bed','shelf','desk','bedside','moon'];

const RELATIONS = [
  { id: 'shelf-above-bed', label: 'ESTANTE ACIMA DA CAMA', test: (room) => room.shelf.y < room.bed.y - 8 },
  { id: 'moon-above-bed', label: 'LUA ACIMA DA CAMA', test: (room) => room.moon.y < room.bed.y - 8 },
  { id: 'bedside-near-bed', label: 'MESA LATERAL JUNTO À CAMA', test: (room) => room.bedside.x < room.bed.x && Math.abs(room.bedside.y - room.bed.y) < 28 },
  { id: 'desk-right-bed', label: 'ESCRIVANINHA À DIREITA', test: (room) => room.desk.x > room.bed.x },
  { id: 'shelf-aligned-bed', label: 'ESTANTE ALINHADA À CAMA', test: (room) => Math.abs(room.shelf.x - room.bed.x) < 36 }
];

function evaluateRoom(state) {
  const room = state.room || {};
  const moved = REQUIRED_OBJECTS.filter((key) => room[key]?.moved);
  const canEvaluate = moved.length === REQUIRED_OBJECTS.length;
  const verifiedRelations = canEvaluate ? RELATIONS.filter((relation) => relation.test(room)) : [];
  const score = moved.length ? Math.min(99, 80 + moved.length * 2 + verifiedRelations.length) : 0;
  return {
    required: REQUIRED_OBJECTS,
    moved,
    relations: RELATIONS,
    verifiedRelations,
    score,
    ready: canEvaluate && verifiedRelations.length >= 4
  };
}

exports.evaluateRoom = evaluateRoom;
},
